import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']

def comps(g):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            n=(y+dy,x+dx)
                            if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]] and n not in seen:
                                seen.add(n); st.append(n)
                res.append(cells)
    return res

def transform(g):
    g=[row[:] for row in g]
    for cells in comps(g):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        t0,b0,l0,r0=min(ys),max(ys),min(xs),max(xs)
        cols=[]
        t,b,l,r=t0,b0,l0,r0
        while t<=b:
            cols.append(g[t][l]); t+=1; b-=1; l+=1; r-=1
        mp=dict(zip(cols,cols[::-1]))
        for y,x in cells:
            g[y][x]=mp[g[y][x]]
    return g

print(transform(inp)==out)
print(json.dumps(transform(G['Test input'])))

t=transform(inp)
for i,(a,b) in enumerate(zip(t,out)):
    if a!=b: print(i,a,b)
